function install_icon() {
    mkdir -p "$(dirname "$ICON_FILE")"
    base64 -d <<< "$ICON_PNG_B64" > "$ICON_FILE.tmp" 2> /dev/null && mv -f "$ICON_FILE.tmp" "$ICON_FILE"
    rm -f "${OLD_ICON_FILES[@]}"
}

# Lineas Exec/Terminal del acceso del menu: la ventana grafica si hay GTK 3 para Python. Si no, el
# panel en GNOME Terminal a 100x32, donde deja sitio al logo de abajo a la izquierda (a 80x24 la
# ventana lo taparia)
function launcher_exec() {
    # Ruta entre comillas por si lleva espacios (con \, ", ` y $ escapados, como pide el formato .desktop)
    local self=$SELF
    if [[ "$self" =~ [[:space:]\"\`\$\\] ]]; then
        self=$(sed -e 's/[\\"`$]/\\\\&/g' <<< "$self")
        self="\"$self\""
    fi
    if gui_available; then
        printf 'Exec=%s ventana\nTerminal=false\nStartupWMClass=%s\n' "$self" "$GUI_APP_ID"
    elif command -v gnome-terminal > /dev/null; then
        printf 'Exec=gnome-terminal --geometry=100x32 -- %s\nTerminal=false\n' "$self"
    else
        printf 'Exec=%s\nTerminal=true\n' "$self"
    fi
}

# Avisa al menu de aplicaciones de que han cambiado los accesos
function refresh_launchers() {
    command -v update-desktop-database > /dev/null && update-desktop-database -q "$1" 2> /dev/null
    touch "$1"
}

# Si el acceso antiguo esta anclado en el dock de GNOME, el dock lo sigue buscando por su nombre de
# archivo y lanza la version que tiene en cache (con la ruta vieja): se cambia por el nuevo, en su sitio
function replace_favorite() {
    command -v gsettings > /dev/null || return 0
    local favorites=$(gsettings get org.gnome.shell favorite-apps 2> /dev/null)
    [[ "$favorites" == *"'$1'"* ]] || return 0
    if [[ "$favorites" == *"'$2'"* ]]; then
        favorites=${favorites//"'$1', "/}
        favorites=${favorites//", '$1'"/}
        favorites=${favorites//"'$1'"/}
    else
        favorites=${favorites//"'$1'"/"'$2'"}
    fi
    gsettings set org.gnome.shell favorite-apps "$favorites" 2> /dev/null
}

LAUNCHER_DIR="$HOME/.local/share/applications"
LAUNCHER="$LAUNCHER_DIR/nexum.desktop"
# El del paquete (.deb), para todos los usuarios: con el, no hace falta el tuyo
SYSTEM_LAUNCHER=/usr/share/applications/nexum.desktop
OLD_LAUNCHERS=(lampp-version-manager.desktop lvm-instalador.desktop php-version-loader.desktop php-version-manager.desktop)

# ¿Hay acceso del menu (el tuyo o el del paquete)?
function launcher_exists() {
    [ -f "$LAUNCHER" ] || [ -f "$SYSTEM_LAUNCHER" ]
}

# Pone al dia los accesos creados por versiones anteriores (nombre, icono y lo que abren)
function update_launchers() {
    local apps=$LAUNCHER_DIR launcher=$LAUNCHER

    # El acceso antiguo se renombra: GNOME no siempre relee un .desktop que cambia de contenido,
    # pero con otro nombre de archivo lo trata como una aplicacion nueva (nombre e icono incluidos)
    local old changed=0
    for old in "${OLD_LAUNCHERS[@]/#/$apps/}"; do
        [ -f "$old" ] || continue
        replace_favorite "$(basename "$old")" "$(basename "$launcher")"
        if [ -f "$launcher" ]; then
            rm -f "$old"
        else
            mv -f "$old" "$launcher"
        fi
        changed=1
    done

    # Un acceso creado por una version anterior se actualiza al nombre y al icono actuales
    if [ -f "$launcher" ]; then
        cmp -s "$ICON_FILE" <(base64 -d <<< "$ICON_PNG_B64" 2> /dev/null) || install_icon
        if ! grep -qxF "Name=$APP_NAME" "$launcher" || ! grep -qxF "Icon=$ICON_FILE" "$launcher"; then
            sed -i -e "s|^Name=.*|Name=$APP_NAME|" -e "s|^Icon=.*|Icon=$ICON_FILE|" \
                -e "s|^Comment=.*|Comment=Instalar, cambiar y desinstalar versiones de XAMPP y PHP|" "$launcher"
            changed=1
        fi
        local exec_lines=$(launcher_exec)
        # El acceso del paquete (.deb) abre el script de /opt/nexum, que es de root: una copia
        # que se ejecute desde otra carpeta (Descargas, que es tuya y la puede cambiar otro programa)
        # no se lo lleva a ella, porque en esa ventana se escribe la contraseña
        if grep -q '^Exec=.*/opt/\(nexum\|lvm-instalador\)/' "$launcher" && [[ "$SELF" != /opt/nexum/* ]]; then
            exec_lines=$(grep -E '^(Exec|Terminal|StartupWMClass)=' "$launcher")
        fi
        if [ "$(grep -E '^(Exec|Terminal|StartupWMClass)=' "$launcher")" != "$exec_lines" ]; then
            # Se quitan las lineas viejas y se ponen las nuevas detras de Comment=
            awk -v lines="$exec_lines" '/^(Exec|Terminal|StartupWMClass)=/ { next } { print } /^Comment=/ { print lines }' \
                "$launcher" > "$launcher.tmp" && mv -f "$launcher.tmp" "$launcher"
            changed=1
        fi
    fi
    [ $changed -eq 1 ] && refresh_launchers "$apps"
    if launcher_exists; then
        for old in "${OLD_LAUNCHERS[@]}"; do
            replace_favorite "$old" "$(basename "$launcher")"
        done
    fi
}

# Crea el acceso del menu de aplicaciones
function write_launcher() {
    mkdir -p "$LAUNCHER_DIR"
    install_icon
    cat > "$LAUNCHER" <<EOF
[Desktop Entry]
Type=Application
Name=$APP_NAME
Comment=Instalar, cambiar y desinstalar versiones de XAMPP y PHP
$(launcher_exec)
Icon=$ICON_FILE
Categories=Development;
EOF
    chmod +x "$LAUNCHER"
    refresh_launchers "$LAUNCHER_DIR"
}

function offer_command_install() {
    [ "$DRY" -eq 1 ] && return 0

    local marker="$LOG_DIR/.accesos-ofrecidos-nexum"
    local need_cmd=0 need_launcher=0

    update_launchers

    # Comandos de versiones anteriores: nexum que apunta a otro archivo del instalador se reapunta, y
    # lvm-instalador y pvm-instalador (los nombres de antes) se quitan. lvm, solo si es un enlace a un
    # lvm-instalador.sh (el de este programa): cualquier otro lvm es de otro programa y no se toca.
    # Se ofrece aunque ya se ofreciera antes
    local link old_links=() drop_links=()
    # (los que llevan al de /opt/nexum, el del paquete, no se tocan: es de root y los pone el paquete)
    link=/usr/local/bin/nexum
    [ -L "$link" ] && [ "$(readlink "$link")" != "$SELF" ] \
        && [[ "$(readlink "$link")" == */nexum.sh || "$(readlink "$link")" == */[lp]vm-instalador.sh ]] \
        && [[ "$(readlink "$link")" != /opt/nexum/* ]] && old_links+=("$link")
    for link in /usr/local/bin/lvm-instalador /usr/local/bin/pvm-instalador; do
        [ -L "$link" ] && [[ "$(readlink "$link")" == */*-instalador.sh ]] && drop_links+=("$link")
    done
    link=/usr/local/bin/lvm
    [ -L "$link" ] && [[ "$(readlink "$link")" == *lvm-instalador.sh ]] && drop_links+=("$link")

    [ -f "$marker" ] && [ ${#old_links[@]} -eq 0 ] && [ ${#drop_links[@]} -eq 0 ] && return 0
    command -v nexum > /dev/null || need_cmd=1
    [ ${#old_links[@]} -gt 0 ] || [ ${#drop_links[@]} -gt 0 ] && need_cmd=1
    launcher_exists || need_launcher=1
    [ $need_cmd -eq 0 ] && [ $need_launcher -eq 0 ] && return 0

    mkdir -p -m 700 "$LOG_DIR"
    touch "$marker"

    local text="¿Quieres crear accesos directos para abrir este instalador facilmente?\n\n"
    [ $need_launcher -eq 1 ] && text+="  - Icono '$APP_NAME' en el menu de aplicaciones\n"
    command -v nexum > /dev/null || text+="  - Comando 'nexum' en la terminal ('nexum use 8.4', 'nexum ventana'...)\n"
    for link in "${old_links[@]}"; do
        text+="  - Comando '$(basename "$link")' (ya existe): que abra este archivo\n"
    done
    for link in "${drop_links[@]}"; do
        text+="  - Quitar el comando antiguo '$(basename "$link")' (ahora es 'nexum')\n"
    done
    text+="\nApuntaran a: $SELF\n(no muevas ni borres este archivo despues)"

    ui_yesno "$text" || return 0

    [ $need_launcher -eq 1 ] && write_launcher

    if [ $need_cmd -eq 1 ]; then
        [ "$UI" == "whiptail" ] && clear
        echo "Para crear el comando se necesita la contraseña de administrador (sudo):"
        command -v nexum > /dev/null || sudo ln -sf "$SELF" /usr/local/bin/nexum
        for link in "${old_links[@]}"; do sudo ln -sfn "$SELF" "$link"; done
        for link in "${drop_links[@]}"; do sudo rm -f "$link"; done
    fi

    ui_msg "Accesos creados. A partir de ahora puedes abrir el instalador desde el menu de aplicaciones o escribiendo 'nexum' en la terminal."
}

# Acerca de: que hace el instalador y la lista de versiones con sus cambios (la ultima, arriba)
ABOUT_TEXT="Herramientas de desarrollo web en local. Para Linux.

QUE HACE
- Instala varias versiones de PHP, de la 7.4 a la 8.5 y cualquier parche
  (8.3.10...), cada una con su propia pila: Apache, PHP-FPM, MariaDB,
  ProFTPD, Perl y phpMyAdmin, en /opt/lampp-X.Y.Z y con sus propias bases
  de datos. Cada rama de PHP lleva componentes compatibles entre si.
- Instala XAMPP completos para proyectos antiguos (equipos x86_64).
- Solo hay una versión activa (/opt/lampp). Se cambia sin tocar los
  proyectos de /opt/htdocs ni los virtual hosts.
- Actualiza cada versión a los últimos parches de su rama, muestra sus
  bases de datos y desinstala versiones (con copia en ~/nexum-backups,
  si se pide).
- No instala PHP ni MariaDB en el sistema.
- Correo de pruebas: lo que mandan las webs locales va a Mailpit y no
  llega a nadie.

VERSIONES

1.57.13 (11 nov 2026)
- Dominios y hosts: arriba, a la izquierda, el recuadro con los dominios
  falseados (también los .local) y, a su derecha, el nuevo proyecto con
  dominio falseado; debajo, los dominios de los vhosts en dos columnas.
- Los avisos de abajo, más grandes y en forma de píldora, con el logotipo
  de Nexum y un borde con los colores de su icono.
- Configuración, General, Registro de tareas: se ven 4 (con más, la
  lista se desplaza en su recuadro) y «Vaciar el registro…» borra los de
  las tareas que ya han acabado, sin ir a Limpieza.
- Mac: el diálogo del túnel abierto se veía con la dirección y la
  contraseña unas encima de otras. En Linux no cambia nada.

1.57.12 (10 nov 2026)
- Aviso «Hay vhosts de carpetas que ya no existen»: los proyectos con
  su vhost pero sin su carpeta en htdocs (Apache avisaba de cada uno al
  arrancar: «AH00112: Warning: DocumentRoot [...] does not exist»), con
  «Quitarlos». Solo cambia el fichero de vhosts: las carpetas, las BBDD
  y /etc/hosts no se tocan. En la terminal: nexum vhosts-sin-carpeta
  [quitar].
- Compartir (túnel): la dirección y la contraseña, cada una en su
  recuadro con su «Copiar», para mandarlas por separado (sin «Copiar
  para enviar», que las juntaba).
- Ya no piden la contraseña de administrador lo que no la necesita:
  compartir (el túnel), Clonar y Traer cambios, borrar una BBDD y
  «Confiar» en el certificado de Docker. Cargar un .sql la pide solo si
  va a vaciar una caché de tienda que es del administrador.
- Cancelar «¿Instalar Mailpit?» deja el correo de pruebas apagado.
- «Vaciar la caché de la tienda» (⋮) va por la carpeta del proyecto: ya
  no falla si varias carpetas usan la misma BBDD.
- Nuevo proyecto con dominio falseado: si el dominio ya tiene vhost con
  esa carpeta, se usa; si lleva a otra, se dice antes de empezar.
- «Imágenes de producción» (antes «Importar») en el visor.
- Borrar de Docker, con la casilla «Guardar antes una copia» (nexum
  docker-borrar <nombre> --copia). Parar el Apache de Docker pregunta
  antes qué proyectos dejan de verse.
- Textos que no cuadraban: «Actualizar las imágenes» (rehace las de
  todas sus versiones), «Eliminar de Docker (PHP 8.4)…», la barrera
  recarga Apache (no lo reinicia), «Registros de <carpeta>» al limpiar
  un proyecto, erratas y la ayuda de la terminal con todas las órdenes.
- Seguridad: al encender o apagar la barrera entre webs, el Apache de
  Docker se pone al día al momento (antes de esto, solo al arrancar).
- El + de «Entorno» propone el proyecto del visor, y «En Docker…» abre
